const getOutgoingTransfers = `-- name: GetOutgoingTransfers :many
SELECT
    t.id,
    t.student_id,
    t.from_school,
    t.to_school,
    t.status,
    t.date_initiated,
    t.date_accepted,
    t.reason,
    t.rejection_reason,
    s.student_number,
    s.first_name AS student_first_name,
    s.last_name AS student_last_name,
    fs.name AS from_school_name,
    ts.name AS to_school_name
FROM
    transfers t
    JOIN students s ON s.id = t.student_id
    JOIN schools fs ON fs.id = t.from_school
    JOIN schools ts ON ts.id = t.to_school
WHERE
    t.from_school = $1
ORDER BY t.date_initiated DESC, t.id DESC
`

type GetOutgoingTransfersRow struct {
	ID               int32
	StudentID        int32
	FromSchool       int32
	ToSchool         int32
	Status           sql.NullString
	DateInitiated    sql.NullTime
	DateAccepted     sql.NullTime
	Reason           sql.NullString
	RejectionReason  sql.NullString
	StudentNumber    string
	StudentFirstName string
	StudentLastName  string
	FromSchoolName   string
	ToSchoolName     string
}

func (q *Queries) GetOutgoingTransfers(ctx context.Context, fromSchool int32) ([]GetOutgoingTransfersRow, error) {
	rows, err := q.db.QueryContext(ctx, getOutgoingTransfers, fromSchool)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetOutgoingTransfersRow
	for rows.Next() {
		var i GetOutgoingTransfersRow
		if err := rows.Scan(
			&i.ID,
			&i.StudentID,
			&i.FromSchool,
			&i.ToSchool,
			&i.Status,
			&i.DateInitiated,
			&i.DateAccepted,
			&i.Reason,
			&i.RejectionReason,
			&i.StudentNumber,
			&i.StudentFirstName,
			&i.StudentLastName,
			&i.FromSchoolName,
			&i.ToSchoolName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

