const getSchoolReport = `-- name: GetSchoolReport :many
SELECT
    sc.id,
    sc.name,
    sc.school_number,
    d.id AS district_id,
    d.name AS district_name,
    r.id AS region_id,
    r.name AS region_name,
    COALESCE(l.learners, 0)::bigint AS student_count,
    COALESCE(l.male, 0)::bigint AS male_count,
    COALESCE(l.female, 0)::bigint AS female_count,
    COALESCE(l.disability, 0)::bigint AS disability_count,
    COALESCE(ti.moves, 0)::bigint AS transfers_in,
    COALESCE(tout.moves, 0)::bigint AS transfers_out,
    COALESCE(ti.pending, 0)::bigint AS pending_in,
    e.jce_pass_rate,
    e.msce_pass_rate,
    -- Calculated from Term 3 marks (the exam results); preferred over the recorded rates
    tr.jce_pass_rate AS term_jce_pass_rate,
    tr.msce_pass_rate AS term_msce_pass_rate
FROM
    schools sc
    JOIN districts d ON d.id = sc.district_id
    JOIN regions r ON r.id = d.region_id
    LEFT JOIN exam_results e ON e.school_id = sc.id
        AND e.academic_year_id = $1::int
    LEFT JOIN term_reports tr ON tr.school_id = sc.id AND tr.term = 3
        AND tr.academic_year_id = $1::int
    -- Counted once per table rather than once per school
    LEFT JOIN (
        SELECT school_id, COUNT(*) AS learners, COUNT(*) FILTER (WHERE gender = 'Male') AS male,
            COUNT(*) FILTER (WHERE gender = 'Female') AS female, COUNT(*) FILTER (WHERE disability) AS disability
        FROM students WHERE status = 'Active' GROUP BY school_id
    ) l ON l.school_id = sc.id
    LEFT JOIN (
        SELECT to_school, COUNT(*) AS moves, COUNT(*) FILTER (WHERE status = 'Pending') AS pending
        FROM transfers GROUP BY to_school
    ) ti ON ti.to_school = sc.id
    LEFT JOIN (SELECT from_school, COUNT(*) AS moves FROM transfers GROUP BY from_school) tout ON tout.from_school = sc.id
WHERE
    ($2::int IS NULL OR r.id = $2::int)
    AND ($3::int IS NULL OR d.id = $3::int)
ORDER BY r.name, d.name, sc.name
`

type GetSchoolReportParams struct {
	AcademicYearID sql.NullInt32
	RegionID       sql.NullInt32
	DistrictID     sql.NullInt32
}

type GetSchoolReportRow struct {
	ID               int32
	Name             string
	SchoolNumber     string
	DistrictID       int32
	DistrictName     string
	RegionID         int32
	RegionName       string
	StudentCount     int64
	MaleCount        int64
	FemaleCount      int64
	DisabilityCount  int64
	TransfersIn      int64
	TransfersOut     int64
	PendingIn        int64
	JcePassRate      sql.NullString
	MscePassRate     sql.NullString
	TermJcePassRate  sql.NullFloat64
	TermMscePassRate sql.NullFloat64
}

// One row per school for the admin reports page. Region and district filters are
// optional; pass rates come from the given academic year and are NULL when not recorded.
func (q *Queries) GetSchoolReport(ctx context.Context, arg GetSchoolReportParams) ([]GetSchoolReportRow, error) {
	rows, err := q.db.QueryContext(ctx, getSchoolReport, arg.AcademicYearID, arg.RegionID, arg.DistrictID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetSchoolReportRow
	for rows.Next() {
		var i GetSchoolReportRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.SchoolNumber,
			&i.DistrictID,
			&i.DistrictName,
			&i.RegionID,
			&i.RegionName,
			&i.StudentCount,
			&i.MaleCount,
			&i.FemaleCount,
			&i.DisabilityCount,
			&i.TransfersIn,
			&i.TransfersOut,
			&i.PendingIn,
			&i.JcePassRate,
			&i.MscePassRate,
			&i.TermJcePassRate,
			&i.TermMscePassRate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

