const upsertMarks = `-- name: UpsertMarks :exec
INSERT INTO student_marks (student_id, subject_id, academic_year_id, term, mark, school_id, recorded_by)
SELECT
    unnest($1::int[]),
    unnest($2::int[]),
    $3::int,
    $4::int,
    unnest($5::int[]),
    $6::int,
    $7::int
ON CONFLICT (student_id, subject_id, academic_year_id, term) DO UPDATE
SET
    mark = EXCLUDED.mark,
    school_id = EXCLUDED.school_id,
    recorded_by = EXCLUDED.recorded_by,
    updated_at = CURRENT_TIMESTAMP
`

type UpsertMarksParams struct {
	StudentIds     []int32
	SubjectIds     []int32
	AcademicYearID int32
	Term           int32
	Marks          []int32
	SchoolID       int32
	RecordedBy     sql.NullInt32
}

// Saves a batch of marks for one academic year and term; the arrays are parallel.
func (q *Queries) UpsertMarks(ctx context.Context, arg UpsertMarksParams) error {
	_, err := q.db.ExecContext(ctx, upsertMarks,
		pq.Array(arg.StudentIds),
		pq.Array(arg.SubjectIds),
		arg.AcademicYearID,
		arg.Term,
		pq.Array(arg.Marks),
		arg.SchoolID,
		arg.RecordedBy,
	)
	return err
}

const withdrawNotice = `-- name: WithdrawNotice :one
WITH withdrawn AS (
    UPDATE notices
    SET withdrawn_at = CURRENT_TIMESTAMP, withdrawn_reason = $1::text
    WHERE notices.id = $2
        AND notices.kind = 'NOTICE'
        AND notices.sender_party_type = $3::text
        AND notices.sender_party_id = $4::int
        AND notices.withdrawn_at IS NULL
    RETURNING notices.id
),
logged AS (
    INSERT INTO audit_logs (entity_type, entity_id, action, actor_user_id, actor_name, actor_role, actor_school_id, note)
    SELECT 'notice', withdrawn.id, 'Withdrawn', u.id, u.name, u.role, u.school_id, $1::text
    FROM withdrawn LEFT JOIN users u ON u.id = $5::int
)
SELECT withdrawn.id FROM withdrawn
`

type WithdrawNoticeParams struct {
	Reason          string
	NoticeID        int32
	SenderPartyType string
	SenderPartyID   int32
	UserID          int32
}

func (q *Queries) WithdrawNotice(ctx context.Context, arg WithdrawNoticeParams) (int32, error) {
	row := q.db.QueryRowContext(ctx, withdrawNotice,
		arg.Reason,
		arg.NoticeID,
		arg.SenderPartyType,
		arg.SenderPartyID,
		arg.UserID,
	)
	var id int32
	err := row.Scan(&id)
	return id, err
}
